      var html = '<div class="wrap"><h2>\u8BC4\u6D4B\u8BB0\u5F55</h2><div class="pagination"><button id="btnPrev" ' + (currentPage <= 1 ? "disabled" : "") + "><</button><span>" + currentPage + '</span><button id="btnNext" ' + (currentPage >= totalPages ? "disabled" : "") + ">></button></div>" + filterHtml + '<div class="records-wrap"><div class="status-table-holder"><div class="header-row"><span class="h-id">#ID</span><span class="h-prob">\u9898\u76EE</span><span class="h-user">\u7528\u6237</span><span>\u5206\u6570</span><span class="h-right">\u65F6\u95F4</span><span class="h-right">\u5185\u5B58</span><span class="h-right">\u4EE3\u7801</span><span>\u7F16\u8BD1\u5668</span><span class="h-right">\u63D0\u4EA4\u65F6\u95F4</span></div>' + recordsHtml + "</div></div></div>";
